class CreativeStudioController extends Controller {
 private function access(Request $r):void{abort_unless(CreativeAccess::staff($r->user()),403);}
 public function index(Request $r){$this->access($r);return view('portal.creative.studio',['briefs'=>\App\Models\Task::where('department','creatives')->realWork()->latest()->paginate(5,['*'],'b_page'),'designs'=>Asset::where('type','design')->latest()->paginate(5,['*'],'d_page'),'creativeComments'=>\App\Models\CreativeComment::with('user','task')->latest()->paginate(5,['*'],'c_page'),'creativeLead'=>CreativeAccess::lead($r->user()),'legacyDesigns'=>Asset::where('type','design')->latest()->paginate(8)]);}
 private function query(Request $r){$r->validate(['q'=>'nullable|string|max:150','assignee'=>'nullable|integer|min:1','department'=>['nullable',Rule::in(array_keys(config('performance.departments')))],'stage'=>['nullable',Rule::in(array_keys(config('creative.stages')))],'priority'=>'nullable|in:Low,Medium,High,Urgent','from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d|after_or_equal:from','page'=>'nullable|integer|min:1','per_page'=>'nullable|integer|min:1|max:120','sort'=>'nullable|in:newest,deadline,oldest,title','view'=>'nullable|in:overview,board,calendar,showcase,workload,reviews,table,presentation,activity']);
  return CreativeRequest::visibleTo($r->user())->when($r->filled('q'),fn($q)=>$q->where(fn($q)=>$q->where('title','like','%'.$r->q.'%')->orWhere('reference','like','%'.$r->q.'%')->orWhere('client','like','%'.$r->q.'%')->orWhere('brief','like','%'.$r->q.'%')->orWhereHas('requester',fn($q)=>$q->where('name','like','%'.$r->q.'%'))))->when($r->filled('assignee'),fn($q)=>$q->where('assignee_id',$r->assignee))->when($r->filled('department'),fn($q)=>$q->where('department',$r->department))->when($r->filled('stage'),fn($q)=>$q->where('stage',$r->stage))->when(!$r->filled('stage'),fn($q)=>$q->where('stage','!=','archived'))->when($r->filled('priority'),fn($q)=>$q->where('priority',$r->priority))->when($r->filled('from')||$r->filled('to'),function($q)use($r){
   $from=$r->filled('from')?Carbon::parse($r->from)->startOfDay():Carbon::parse('1900-01-01');$to=$r->filled('to')?Carbon::parse($r->to)->endOfDay():Carbon::parse('9999-12-31');
   $q->where(function($dates)use($from,$to){
    foreach(['received_at','requested_deadline','internal_eta','submitted_at','reviewed_at','completed_at'] as $key)$dates->orWhereBetween($key,[$from,$to]);
    $dates->orWhere(fn($window)=>$window->where('planned_start','<=',$to)->where('internal_eta','>=',$from));
    \App\Services\Creative\CreativeReportingPeriod::includeHistory($dates,$from,$to);
   });
  });
 }
 public function data(Request $r){$this->access($r);$q=$this->query($r);$allSummaryQuery=clone $q;$summary=(clone $q)->where('is_group',false)->selectRaw('stage, COUNT(*) AS total')->groupBy('stage')->pluck('total','stage');$rows=$q->reorder(match($r->input('sort','newest')){'deadline'=>'requested_deadline','title'=>'title',default=>'id'},$r->input('sort','newest')==='newest'?'desc':'asc')->with(['requester','assignee','reviewer','attachments','task','firstSubmission'])->paginate($r->integer('per_page',48))->withQueryString();
  $staff=User::humanAccounts()->whereIn('department',User::departmentAliases('creatives'))->where('status','active')->orderBy('name')->get();
  $week=$r->filled('from')?Carbon::parse($r->from):now()->startOfWeek();
  return response()->json(['planning_summary'=>['unassigned'=>(clone $allSummaryQuery)->where('is_group',false)->whereNull('assignee_id')->whereNotIn('stage',['completed','archived'])->count(),'eta_conflicts'=>(clone $allSummaryQuery)->whereColumn('internal_eta','>','requested_deadline')->whereNotIn('stage',['completed','archived'])->count(),'due_next_seven_days'=>(clone $allSummaryQuery)->whereBetween('requested_deadline',[now(),now()->addDays(7)])->whereNotIn('stage',['completed','archived'])->count()],'items'=>$rows->getCollection()->map(fn($item)=>app(CreativeProjection::class)->item($item,$r->user())),'pagination'=>['page'=>$rows->currentPage(),'last'=>$rows->lastPage(),'total'=>$rows->total()],'summary'=>$summary,'completion_summary'=>['verified'=>(clone $allSummaryQuery)->where('is_group',false)->where('stage','completed')->whereNotNull('completed_at')->count(),'historical_reported'=>(clone $allSummaryQuery)->where('is_group',false)->where('stage','completed')->whereNull('completed_at')->count()],'stages'=>config('creative.stages'),'types'=>config('creative.types'),'departments'=>config('performance.departments'),'staff'=>$staff->map(fn($u)=>['id'=>$u->id,'name'=>$u->name,'photo'=>$u->profilePhotoUrl()]),'reviewers'=>User::humanAccounts()->where('status','active')->get()->filter(fn($u)=>CreativeAccess::lead($u))->map(fn($u)=>['id'=>$u->id,'name'=>$u->name,'department'=>User::normalizeDepartmentKey($u->department)])->values(),'capacity_period'=>['from'=>$week->copy()->startOfWeek()->toDateString(),'to'=>$week->copy()->endOfWeek()->toDateString()],'capacity'=>app(CreativeCapacity::class)->summary($r->user(),$week->copy()->startOfWeek(),$week->copy()->endOfWeek()),'can_plan'=>CreativeAccess::lead($r->user()),'actor'=>$r->user()->id,'review_business_days'=>config('creative.review_business_days'),'kpi_snapshot'=>app(\App\Services\Creative\CreativeKpiSnapshot::class)->forPeriod($week->copy()->startOfMonth(),$week->copy()->endOfMonth())])->header('Cache-Control','private, no-store');
 }
 public function show(Request $r,CreativeRequest $creative){$this->access($r);abort_unless(CreativeAccess::view($r->user(),$creative),404);$r->validate(['history_page'=>'nullable|integer|min:1','feedback_page'=>'nullable|integer|min:1']);return response()->json(app(CreativeProjection::class)->detail($creative,$r->user(),$r->integer('history_page',1),$r->integer('feedback_page',1)))->header('Cache-Control','private, no-store');}
 public function store(Request $r){$this->access($r);$d=$r->validate(['title'=>'required|string|min:5|max:150','brief'=>'required|string|min:20|max:10000','creative_type'=>['required',Rule::in(config('creative.types'))],'client'=>'nullable|string|max:150','priority'=>'required|in:Low,Medium,High,Urgent','visibility'=>'required|in:shared,restricted','requested_deadline'=>'required|date|after:now','reported_external_at'=>'nullable|date|before_or_equal:now','reference_url'=>'nullable|url:https|max:2000']);$item=app(CreativeWorkflow::class)->create($r->user(),$d);return response()->json(['id'=>$item->id,'message'=>'Brief submitted. The shared timeline and notifications have been recorded.'],201);}
 public function split(Request $r,CreativeRequest $creative){$this->access($r);$d=$r->validate(['revision'=>'required|integer|min:1','reason'=>'required|string|min:5|max:2000','parts'=>'required|array|min:2|max:12','parts.*.title'=>'required|string|min:5|max:150','parts.*.brief'=>'required|string|min:20|max:10000','parts.*.priority'=>'nullable|in:Low,Medium,High,Urgent','parts.*.requested_deadline'=>'nullable|date|after:now']);$item=app(CreativeWorkflow::class)->split($creative,$r->user(),$d);return response()->json(['id'=>$item->id,'message'=>'Brief split into work packages. Assign each part through HOD Planning.']);}
 public function previewPlan(Request $r,CreativeRequest $creative){
  $this->access($r);abort_unless(CreativeAccess::lead($r->user()),403);
  $d=$r->validate(['assignee_id'=>'required|integer|exists:users,id','planned_start'=>'required|date','internal_eta'=>'required|date|after_or_equal:planned_start','requested_deadline'=>'required|date','estimated_hours'=>'required|numeric|min:0.25|max:2000']);
  abort_if(Carbon::parse($d['planned_start'])->diffInDays(Carbon::parse($d['internal_eta']))>366,422,'Use a work window of no more than one year.');
  $assignee=User::findOrFail($d['assignee_id']);abort_unless($assignee->isActive()&&User::normalizeDepartmentKey($assignee->department)==='creatives',422);
  $candidate=clone $creative;$candidate->fill($d);$capacity=app(CreativeCapacity::class);
  abort_unless($capacity->workingDates($candidate->planned_start,$candidate->internal_eta,$assignee->id),422,'Choose a window with an available working day.');
  return response()->json(['warnings'=>$capacity->warnings($candidate),'message'=>'Preview only. Nothing has been saved.'])->header('Cache-Control','private, no-store');
 }
 public function plan(Request $r,CreativeRequest $creative){$this->access($r);$d=$r->validate(['revision'=>'required|integer|min:1','assignee_id'=>'required|integer|exists:users,id','reviewer_id'=>'required|integer|exists:users,id','planned_start'=>'required|date','internal_eta'=>'required|date|after_or_equal:planned_start','requested_deadline'=>'required|date','estimated_hours'=>'required|numeric|min:0.25|max:2000','performance_weight'=>'nullable|integer|min:1|max:100','priority'=>'required|in:Low,Medium,High,Urgent','reason'=>'required|string|min:5|max:2000','override_reason'=>'nullable|string|max:2000','blocker'=>'nullable|string|max:2000','blocker_owner'=>'nullable|string|max:150']);if(Carbon::parse($d['planned_start'])->diffInDays(Carbon::parse($d['internal_eta']))>366)throw \Illuminate\Validation\ValidationException::withMessages(['internal_eta'=>'Plan a work window of no more than one year; split longer work into milestones.']);$item=app(CreativeWorkflow::class)->plan($creative,$r->user(),$d);return response()->json(['id'=>$item->id,'message'=>'Plan saved. Original brief receipt and delivery history are retained.']);}
 public function transition(Request $r,CreativeRequest $creative){
  $this->access($r);$d=$r->validate(['revision'=>'required|integer|min:1','stage'=>['required',Rule::in(array_keys(config('creative.stages')))],'reason'=>'nullable|string|max:3000','reference_url'=>'nullable|url:https|max:2000','feedback_type'=>'nullable|in:correction,scope_change,clarification','quality_score'=>'nullable|numeric|min:0|max:100','client_approved'=>'nullable|boolean','evidence_images'=>'nullable|array|max:6','evidence_images.*'=>'file|image|mimes:jpg,jpeg,png,webp|max:8192|dimensions:max_width=6000,max_height=6000']);$d+=['reason'=>'','quality_score'=>null];
  $paths=[];
  try{$item=DB::transaction(function()use($r,$creative,$d,&$paths){
   $locked=CreativeRequest::lockForUpdate()->findOrFail($creative->id);
   abort_unless(in_array($d['stage'],app(CreativeWorkflow::class)->allowed($locked,$r->user()),true),403);
   abort_if($locked->revision!==(int)$d['revision'],409,'This work changed. Refresh before saving.');
   if($r->hasFile('evidence_images')){
    abort_unless($d['stage']==='in_review',422,'Add completion images when submitting work for review.');
    foreach($r->file('evidence_images') as $file){app(\App\Services\Creative\CreativeUploadScreening::class)->check($file);$path=$file->store('creative-studio','local');abort_unless($path,503);$paths[]=$path;
     $attachment=$locked->attachments()->create(['uploaded_by'=>$r->user()->id,'path'=>$path,'mime'=>$file->getMimeType(),'original_name'=>mb_substr(basename($file->getClientOriginalName()),0,240),'size'=>$file->getSize(),'kind'=>'deliverable','iteration'=>$locked->iteration]);
     app(CreativeWorkflow::class)->event($locked,$r->user(),'completion_evidence_added',[],'Completion image attached: '.$attachment->original_name);
    }
   }
   return app(CreativeWorkflow::class)->transition($locked,$r->user(),$d);
  });}catch(\Throwable $e){foreach($paths as $path)Storage::disk('local')->delete($path);throw $e;}
  return response()->json(['id'=>$item->id,'message'=>'Stage and evidence saved. The shared timeline and notifications are updated.']);
 }
 public function comment(Request $r,CreativeRequest $creative){$this->access($r);abort_unless(CreativeAccess::view($r->user(),$creative),404);$d=$r->validate(['body'=>'required|string|min:2|max:3000','reference_url'=>'nullable|url:https|max:2000']);DB::transaction(function()use($r,$creative,$d){$creative->updates()->create(['author_id'=>$r->user()->id,'kind'=>'comment',...$d]);app(CreativeWorkflow::class)->event($creative,$r->user(),'comment_added',[],'Shared comment added.');app(CreativeWorkflow::class)->notify($creative,[$creative->assignee_id,$creative->requester_id,$creative->reviewer_id],'Creative discussion updated',$creative->reference.' has a new shared comment.','creative-comment:'.$creative->id.':'.\Illuminate\Support\Str::uuid());});return response()->json(['message'=>'Comment added to the shared history.']);}
 public function acknowledge(Request $r,CreativeRequest $creative){$this->access($r);abort_unless($r->user()->id===$creative->assignee_id,403);DB::transaction(function()use($r,$creative){$item=CreativeRequest::lockForUpdate()->findOrFail($creative->id);abort_unless($item->assignee_id===$r->user()->id,403);if(!$item->acknowledged_at){$item->acknowledged_at=now();$item->revision++;$item->save();app(CreativeWorkflow::class)->event($item,$r->user(),'acknowledged',[],'Assigned creative acknowledged the brief in the portal.');}});return response()->json(['message'=>'Acknowledgement timestamp recorded.']);}
 public function upload(Request $r,CreativeRequest $creative){$this->access($r);abort_unless(CreativeAccess::view($r->user(),$creative)&&(CreativeAccess::owner($r->user(),$creative)||$r->user()->id===$creative->requester_id),403);$r->validate(['file'=>'required|file|mimes:jpg,jpeg,png,webp,pdf,mp4,webm,zip,pptx,docx,xlsx,psd|max:20480','kind'=>'required|in:brief,reference,deliverable']);$file=$r->file('file');app(\App\Services\Creative\CreativeUploadScreening::class)->check($file);$path=$file->store('creative-studio','local');abort_unless($path,503);try{DB::transaction(function()use($r,$creative,$file,$path){$locked=CreativeRequest::lockForUpdate()->findOrFail($creative->id);abort_unless(CreativeAccess::view($r->user(),$locked)&&(CreativeAccess::owner($r->user(),$locked)||$r->user()->id===$locked->requester_id),403);$locked->attachments()->create(['uploaded_by'=>$r->user()->id,'path'=>$path,'mime'=>$file->getMimeType(),'original_name'=>mb_substr(basename($file->getClientOriginalName()),0,240),'size'=>$file->getSize(),'kind'=>$r->kind,'iteration'=>$locked->iteration]);app(CreativeWorkflow::class)->event($locked,$r->user(),'attachment_added',[],'Attachment retained: '.$file->getClientOriginalName());});}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}return response()->json(['message'=>'File saved securely against this brief.']);}
 public function attachment(Request $r,CreativeAttachment $attachment){$this->access($r);abort_unless(CreativeAccess::view($r->user(),$attachment->request),404);abort_unless(Storage::disk('local')->exists($attachment->path),404);$headers=['Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff'];if(!$r->boolean('download')&&in_array($attachment->mime,['image/jpeg','image/png','image/webp','video/mp4','video/webm']))return response()->file(Storage::disk('local')->path($attachment->path),$headers)->setPrivate();return Storage::disk('local')->download($attachment->path,$attachment->original_name,$headers);}
 public function capacity(Request $r){$this->access($r);abort_unless(CreativeAccess::lead($r->user()),403);$d=$r->validate(['user_id'=>'required|integer|exists:users,id','weekly_hours'=>'required|numeric|min:0|max:80','reason'=>'required|string|min:5|max:1000','starts_on'=>'nullable|date_format:Y-m-d|required_with:ends_on','ends_on'=>'nullable|date_format:Y-m-d|after_or_equal:starts_on|required_with:starts_on']);$user=User::findOrFail($d['user_id']);abort_unless(User::normalizeDepartmentKey($user->department)==='creatives',422);$before=(array)DB::table('creative_capacities')->where('user_id',$user->id)->first();DB::transaction(function()use($r,$d,$before){if(!empty($d['starts_on'])){DB::table('creative_capacity_exceptions')->insert(['user_id'=>$d['user_id'],'starts_on'=>$d['starts_on'],'ends_on'=>$d['ends_on'],'weekly_hours'=>$d['weekly_hours'],'updated_by'=>$r->user()->id,'reason'=>$d['reason'],'created_at'=>now(),'updated_at'=>now()]);}else DB::table('creative_capacities')->updateOrInsert(['user_id'=>$d['user_id']],['weekly_hours'=>$d['weekly_hours'],'updated_by'=>$r->user()->id,'updated_at'=>now(),'created_at'=>now()]);\App\Services\PerformanceWorkflow::record('creative_capacity',$d['user_id'],$r->user()->id,'capacity_updated',$before,collect($d)->only(['weekly_hours','starts_on','ends_on'])->all(),$d['reason']);});return response()->json(['message'=>'Capacity saved. Approved leave and company non-working days are applied.']);}
 public function activity(Request $r){
  $this->access($r);$r->validate(['page'=>'nullable|integer|min:1']);$visible=$this->query($r)->select('creative_requests.id');
  $events=\App\Models\PerformanceEvent::with('actor')->where('entity_type','creative_request')->whereIn('entity_id',$visible)->latest('id')->paginate(30);
  $requests=CreativeRequest::whereIn('id',$events->pluck('entity_id'))->get()->keyBy('id');
  return response()->json(['items'=>$events->map(fn($e)=>['id'=>$e->id,'request_id'=>$e->entity_id,'reference'=>$requests[$e->entity_id]->reference,'title'=>$requests[$e->entity_id]->title,'actor'=>$e->actor?->name?:'Retained Staff History','action'=>$e->action,'reason'=>$e->reason,'at'=>$e->created_at?Carbon::parse($e->created_at)->toIso8601String():null]),'page'=>$events->currentPage(),'last'=>$events->lastPage(),'total'=>$events->total()])->header('Cache-Control','private, no-store');
 }
 public function presentationReport(Request $r,string $format='data'){
  $this->access($r);$d=$r->validate(['period'=>'required|in:weekly,monthly,quarterly,yearly','anchor'=>'required|date_format:Y-m-d','assignee'=>'nullable|integer|min:1','q'=>'nullable|string|max:150']);
  $report=app(\App\Services\Creative\CreativeReport::class)->build($r->user(),$d['period'],$d['anchor'],$d,$format==='pdf');
  if($format==='data'){foreach($report['gallery'] as &$item)unset($item['image']);return response()->json($report)->header('Cache-Control','private, no-store');}
  $pdf=new \Dompdf\Dompdf();$pdf->loadHtml(view('portal.creative.presentation-report',['report'=>$report])->render());$pdf->setPaper('a4','landscape');$pdf->render();return response($pdf->output(),200,['Content-Type'=>'application/pdf','Content-Disposition'=>'attachment; filename="cmih-creative-'.$d['period'].'-'.$report['from'].'.pdf"','Cache-Control'=>'private, no-store']);
 }
 public function export(Request $r,string $format){$this->access($r);abort_unless(in_array($format,['xlsx','pdf']),404);$query=$this->query($r);abort_if((clone $query)->count()>($format==='pdf'?300:10000),422,'Narrow the filters before exporting: PDF supports 300 records and Excel supports 10,000 per report.');$items=$query->with('assignee','requester')->orderBy('id')->get();$headers=['Reference','Project','Client','Requested By','Department','Creative','Stage','Brief Received','Requested Deadline','Internal ETA','First Submission','Review Due','Verified Completion'];$rows=$items->map(fn($i)=>[$i->reference,$i->title,$i->client??'Internal',$i->requester?->name??'Not recorded',config('performance.departments.'.$i->department,$i->department??'Not recorded'),$i->assignee?->name??'Unassigned',CreativeProjection::stageLabel($i),...array_map(fn($key)=>$i->$key?$i->$key->timezone(config('creative.timezone'))->format(in_array($key,['received_at','requested_deadline'])&&$i->legacy?'d M Y':'d M Y H:i').(in_array($key,['received_at','requested_deadline'])&&$i->legacy?' (date only)':''):'Not recorded',['received_at','requested_deadline','internal_eta','first_submitted_at','review_due_at','completed_at'])])->all();
  if($format==='xlsx')return response(app(\App\Services\BrandedSpreadsheet::class)->xlsx([$headers,...$rows]),200,['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','Content-Disposition'=>'attachment; filename="cmih-creative-studio.xlsx"','Cache-Control'=>'private, no-store']);
  $pdf=new \Dompdf\Dompdf();$pdf->loadHtml(view('portal.creative.report',['items'=>$items,'headers'=>$headers,'rows'=>$rows])->render());$pdf->setPaper('a4','landscape');$pdf->render();return response($pdf->output(),200,['Content-Type'=>'application/pdf','Content-Disposition'=>'attachment; filename="cmih-creative-studio.pdf"','Cache-Control'=>'private, no-store']);
 }
